// Writes the three fixture streams of test/fixtures/streams/ (Track 1E, BP1).
//
//   tracer.ndjson      one of every event type this slice emits
//   hero-c04.ndjson    the C04 vector: the shared rule lands first, the in-flight crab is sent around
//   hero-c05.ndjson    the C05 vector: the crab lands first, the shared rule learns of the referrer
//
// Every event is authored here from the event types of 01-core 12.1 and the expectations of
// docs/spec/premise-cases.json — nothing is generated by running an engine. Run it with
// `node scripts/fixtures/write-streams.ts` after editing; the files it writes are the fixture.

import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import type { PoolEvent } from "../../src/protocol/events.ts";
import type { ReplayHeader } from "../../src/protocol/replay.ts";
import { REPLAY_FORMAT } from "../../src/protocol/replay.ts";

const OUT_DIR = join(dirname(fileURLToPath(import.meta.url)), "../../test/fixtures/streams");

/** The pool id every fixture stream serves. */
const POOL = "tidepool";
/** Streams start at this fixed instant so the files are byte-stable. */
const T0 = Date.UTC(2024, 0, 1, 0, 0, 0);

// The tidepool seed (premise-cases.json `pools.tidepool`): the policy file's tier list makes
// creatures/** and world/** `auto`.
const SEED_FILES = [
  { path: ".premise/policy.json", tier: "held" as const },
  { path: "world/energy.js", tier: "auto" as const },
  { path: "world/movement.js", tier: "auto" as const },
  { path: "creatures/fish.js", tier: "auto" as const },
  { path: "creatures/snail.js", tier: "auto" as const },
];

const ENERGY = "world/energy.js#ENERGY_MAX";
const ENERGY_IMPORTS = [
  "creatures/fish.js#(import ../world/energy.js)",
  "creatures/fish.js#spawn",
  "creatures/snail.js#(import ../world/energy.js)",
  "creatures/snail.js#spawn",
];

/** A `PoolEvent` minus the fields the builder assigns; the omit distributes over the union. */
type EventInput = PoolEvent extends infer E ? (E extends PoolEvent ? Omit<E, "n" | "t" | "pool"> : never) : never;

/** One stream under construction: `n` is assigned in push order, `t` tracks `ts`. */
type StreamBuilder = {
  push(body: EventInput): void;
  events: PoolEvent[];
};

function stream(): StreamBuilder {
  const events: PoolEvent[] = [];
  return {
    events,
    push(body) {
      const n = events.length + 1;
      events.push({ ...body, n, t: body.ts + 5, pool: POOL } as PoolEvent);
    },
  };
}

type Push = StreamBuilder["push"];

/** The seed header of every tidepool fixture: pool.state, then pool.files (EM1a flags both false). */
function seed(push: Push, ts: number): void {
  push({
    ts,
    src: "trunk",
    type: "pool.state",
    head_seq: 0,
    head_commit: "seed0000seed0000seed0000seed0000seed0000",
    green_seq: 0,
    landed_seq: 0,
    landed_commit: "seed0000seed0000seed0000seed0000seed0000",
    state: "ready",
    reason: null,
    epoch: 1,
    remote: "https://artifacts.test/tidepool",
    plain_remote: "https://artifacts.test/tidepool-plain",
    rebuild: null,
    unwitnessed: [],
    real_agents: 1,
    max_real_agents: 6,
    synthetic: false,
    summary_only: false,
  });
  push({ ts: ts + 10, src: "trunk", type: "pool.files", files: SEED_FILES });
}

function openAttempt(push: Push, ts: number, intentId: string, attemptId: string, text: string): void {
  push({
    ts,
    src: "trunk",
    type: "intent.created",
    intent_id: intentId,
    text,
    requester: "owner",
    race: false,
    prewritten: false,
  });
  push({
    ts: ts + 10,
    src: "trunk",
    type: "attempt.opened",
    attempt_id: attemptId,
    intent_id: intentId,
    change_id: `c-${attemptId}`,
    agent: "real",
    model: "model-a",
    race: false,
  });
  push({ ts: ts + 20, src: "agent", type: "attempt.repo", attempt_id: attemptId, ok: true, ms: 400, error: null });
  push({
    ts: ts + 30,
    src: "trunk",
    type: "attempt.state",
    attempt_id: attemptId,
    from: "opened",
    to: "working",
    transition: "T1",
    reason: null,
    go_arounds: 0,
    pull_backs: 0,
    right_of_way: false,
  });
}

function accepted(
  push: Push,
  ts: number,
  seq: number,
  attemptId: string,
  intentId: string,
  goArounds: number,
  paths: string[],
  writes: Array<{ kind: "entity" | "file" | "listing"; key: string; old: string; new: string }>,
): void {
  push({
    ts,
    src: "trunk",
    type: "landing.accepted",
    seq,
    batch_id: seq,
    kind: "change",
    attempt_id: attemptId,
    change_id: `c-${attemptId}`,
    intent_id: intentId,
    request_id: null,
    paths,
    writes,
  });
  push({
    ts: ts + 5,
    src: "trunk",
    type: "attempt.state",
    attempt_id: attemptId,
    from: "validated",
    to: "accepted",
    transition: "T15",
    reason: null,
    go_arounds: goArounds,
    pull_backs: 0,
    right_of_way: false,
  });
}

function pushed(
  push: Push,
  ts: number,
  seq: number,
  attemptId: string,
  intentId: string,
  goArounds: number,
  commit: string,
  noteJson: string | null,
  timeToLand: number,
): void {
  push({
    ts,
    src: "trunk",
    type: "landing.landed",
    seq,
    batch_id: seq,
    commit,
    tree: `tree-${seq}`,
    note: `note-${seq}`,
    note_json: noteJson,
    time_to_land_ms: timeToLand,
  });
  push({
    ts: ts + 5,
    src: "trunk",
    type: "batch.pushed",
    batch_id: seq,
    first_seq: seq,
    last_seq: seq,
    main: commit,
    notes: `note-${seq}`,
    tries: 1,
    ms: 300,
  });
  push({
    ts: ts + 10,
    src: "trunk",
    type: "attempt.state",
    attempt_id: attemptId,
    from: "accepted",
    to: "landed",
    transition: "T16",
    reason: null,
    go_arounds: goArounds,
    pull_backs: 0,
    right_of_way: false,
  });
  push({ ts: ts + 15, src: "trunk", type: "intent.state", intent_id: intentId, state: "landed" });
}

function poolState(push: Push, ts: number, headSeq: number, landedSeq: number, landedCommit: string): void {
  push({
    ts,
    src: "trunk",
    type: "pool.state",
    head_seq: headSeq,
    head_commit: landedCommit,
    green_seq: 0,
    landed_seq: landedSeq,
    landed_commit: landedCommit,
    state: "ready",
    reason: null,
    epoch: 1,
    remote: "https://artifacts.test/tidepool",
    plain_remote: "https://artifacts.test/tidepool-plain",
    rebuild: null,
    unwitnessed: [],
    real_agents: 1,
    max_real_agents: 6,
    synthetic: false,
    summary_only: false,
  });
}

