// ---- write the three files in the Replay format of 01-core 12.3 ----

function write(name: string, label: string, synthetic: boolean, events: PoolEvent[]): void {
  const header: ReplayHeader = {
    premise_replay: REPLAY_FORMAT,
    pool: POOL,
    recorded_at: new Date(T0 + 60_000).toISOString(),
    events: events.length,
    synthetic,
    build: "fixtures/1",
    label,
  };
  const text = [JSON.stringify(header), ...events.map((event) => JSON.stringify(event))].join("\n") + "\n";
  writeFileSync(join(OUT_DIR, name), text);
  console.log(`wrote ${name}: ${events.length} events`);
}

